INSERT INTO disaster_demo.claims (id, reference, policy_id, incident_type, incident_at, reported_at, intake_status, description, summary, stage, habitability, access_status, priority, priority_reasons, needs, required_documents, assessment, cost_estimate, updated_at, closed_at) VALUES ('30000000-0000-4000-8000-000000000003', 'CAT-2026-003', '20000000-0000-4000-8000-000000000003', 'flood', '2026-10-20T10:00:00+02:00', '2026-10-22T08:15:00+02:00', 'reported', 'The home is inaccessible. Physical damage has not been confirmed.', 'Confirm access and temporary accommodation needs; do not infer physical damage.', 'collecting_documents', 'unknown', 'restricted', 'P2', '["Home inaccessible; assistance needs require confirmation."]'::jsonb, '[{"code":"accommodation","status":"to_confirm","quantity":1}]'::jsonb, '["photos","address","inventory"]'::jsonb, '{"status":"not_reviewed","source_section_ids":[],"missing_information":[],"fictional":true}'::jsonb, '{"currency":"EUR","gross_cents":null,"approved_cents":null,"paid_cents":0,"lines":[],"fictional":true}'::jsonb, '2026-10-22T08:16:00+02:00', NULL) ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000001', '40000000-0000-4000-8000-000000000001', 0, 'Emergency accommodation', 'DEMO-ACCOMMODATION', NULL, NULL, 'Up to seven nights at EUR 150 per household per night, at most EUR 1,050. Confirm household size, unusability of the main residence, dates and current accommodation need. Extensions require separate review.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000002', '40000000-0000-4000-8000-000000000001', 1, 'Essential items', 'DEMO-ESSENTIAL_ITEMS', NULL, NULL, 'Up to EUR 250 per household for identified essential expenditure. Confirm need and itemised costs.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000003', '40000000-0000-4000-8000-000000000001', 2, 'Electrical inspection and safety', 'DEMO-ELECTRICAL_SAFETY', NULL, NULL, 'Up to EUR 500 for assessed electrical inspection and immediate safety work by a qualified professional. Physical work requires permitted access.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000004', '40000000-0000-4000-8000-000000000001', 3, 'Cleaning and drying', 'DEMO-CLEANING_DRYING', NULL, NULL, 'Up to EUR 3,000 for assessed cleaning and drying. Confirm damage, access, work scope and resource availability.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000005', '40000000-0000-4000-8000-000000000001', 4, 'Moving and temporary storage', 'DEMO-MOVING_STORAGE', NULL, NULL, 'Up to EUR 1,000 to protect recoverable belongings. Do not count the same belongings as both a total loss and intact stored property.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000006', '40000000-0000-4000-8000-000000000001', 5, 'Damaged contents', 'DEMO-CONTENTS', NULL, NULL, 'Up to EUR 30,000 for assessed eligible contents damage. Require an inventory, ownership or value evidence and assessment. No automatic new-for-old settlement.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000007', '40000000-0000-4000-8000-000000000001', 6, 'Insured building repairs', 'DEMO-BUILDING', NULL, NULL, 'Up to EUR 200,000 for assessed eligible damage to the declared owner-occupied main residence. Verify cause and repair scope.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000008', '40000000-0000-4000-8000-000000000001', 7, 'Scope, exclusions and deductible', 'DEMO-SCOPE', NULL, NULL, 'Fictional product only. Excludes personal injury, vehicles, commercial interruption, undeclared property and unrelated or pre-existing damage. Uncertain causation or ground instability requires human review. One EUR 300 deductible applies to combined eligible contents and building damage per household and event, after limits and eligibility assessment. No demo deductible applies to the five assistance benefits. The contractual flood route does not require a CatNat order; CatNat recognition remains unverified and must not be inferred. No booking, payment or coverage decision is real.', 'en') ON CONFLICT (id) DO NOTHING;
INSERT INTO disaster_demo.document_sections (id, document_id, position, title, clause_reference, page_start, page_end, text, language) VALUES ('50000000-0000-4000-8000-000000000009', '40000000-0000-4000-8000-000000000002', 0, 'Declared household and insured residence', 'DEMO-SPECIFIC', NULL, NULL, 'FICTIONAL SPECIFIC TERMS - ALL-DEMO-001
